extension OnboardingView {
    var welcomeStep: some View {
        VStack(spacing: 16) {
            Image(systemName: "lock.shield")
                .font(.system(size: 56))
                .foregroundStyle(Color.accentColor)
                .accessibilityLabel("Privacy shield")
            Text(String(localized: "Your meetings stay on your Mac"))
                .font(.title2.bold())
            Text(
                // swiftlint:disable:next line_length
                "THE RECORD transcribes locally using on-device AI. Nothing is sent to a server. Your recordings, transcripts, and summaries live only on this machine."
            )
            .font(.body)
            .foregroundStyle(.secondary)
            .multilineTextAlignment(.center)
            .frame(maxWidth: 380)
        }
    }

    var micStep: some View {
        VStack(spacing: 16) {
            Image(systemName: vm.micStatus == .granted ? "mic.circle.fill" : "mic.circle")
                .font(.system(size: 56))
                .foregroundStyle(vm.micStatus == .granted ? Color.green : Color.accentColor)
                .accessibilityLabel("Microphone permission")
                .accessibilityValue(vm.micStatus == .granted ? "Granted" : "Not granted")
            Text(String(localized: "Microphone access"))
                .font(.title2.bold())
            Text(
                vm.micStatus == .granted
                    ? "Microphone access granted. THE RECORD can capture your voice."
                    : "THE RECORD needs microphone access to transcribe your speech."
            )
            .font(.body)
            .foregroundStyle(.secondary)
            .multilineTextAlignment(.center)
            .frame(maxWidth: 380)
            if vm.micStatus == .denied {
                openSettingsButton(
                    label: "Open Privacy Settings",
                    url: "x-apple.systempreferences:com.apple.preference.security?Privacy_Microphone"
                )
            } else if vm.micStatus == .notDetermined {
                Button(String(localized: "Allow Microphone Access")) { Task { await vm.requestMicrophone() } }
                    .buttonStyle(.borderedProminent)
            }
        }
        .onReceive(NotificationCenter.default.publisher(for: NSApplication.didBecomeActiveNotification)) { _ in
            Task { await vm.refresh() }
        }
    }

    var audioStep: some View {
        VStack(spacing: 16) {
            Image(systemName: vm.screenGranted ? "waveform.circle.fill" : "waveform.circle")
                .font(.system(size: 56))
                .foregroundStyle(vm.screenGranted ? Color.green : Color.accentColor)
                .accessibilityLabel("System audio permission")
                .accessibilityValue(vm.screenGranted ? "Granted" : "Not granted")
            Text(String(localized: "System audio capture"))
                .font(.title2.bold())
            Text(
                vm.screenGranted
                    // swiftlint:disable:next line_length
                    ? "Screen recording permission granted. THE RECORD can capture meeting audio from apps like Zoom and Teams."
                    :
                    // swiftlint:disable:next line_length
                    "To capture audio from other apps, THE RECORD needs Screen Recording permission. You can skip this and grant it later in System Settings."
            )
            .font(.body)
            .foregroundStyle(.secondary)
            .multilineTextAlignment(.center)
            .frame(maxWidth: 380)
            if !vm.screenGranted {
                openSettingsButton(
                    label: "Open Privacy Settings",
                    url: "x-apple.systempreferences:com.apple.preference.security?Privacy_ScreenCapture"
                )
                .onReceive(
                    NotificationCenter.default
                        .publisher(for: NSApplication.didBecomeActiveNotification)
                ) { _ in
                    Task { await vm.refresh() }
                }
            }
        }
    }

    var calendarStep: some View {
        VStack(spacing: 16) {
            Image(systemName: vm.calendarStatus == .granted ? "calendar.circle.fill" : "calendar.circle")
                .font(.system(size: 56))
                .foregroundStyle(vm.calendarStatus == .granted ? Color.green : Color.accentColor)
                .accessibilityLabel("Calendar permission")
                .accessibilityValue(vm.calendarStatus == .granted ? "Granted" : "Not granted")
            Text(String(localized: "Calendar access"))
                .font(.title2.bold())
            Text(
                vm.calendarStatus == .granted
                    ? "Calendar access granted. THE RECORD can automatically match recordings to your meetings."
                    : "THE RECORD can use your calendar to automatically name and organise recordings. You can skip this and grant it later."
            )
            .font(.body)
            .foregroundStyle(.secondary)
            .multilineTextAlignment(.center)
            .frame(maxWidth: 380)
            if vm.calendarStatus == .denied {
                openSettingsButton(
                    label: "Open Privacy Settings",
                    url: "x-apple.systempreferences:com.apple.preference.security?Privacy_Calendars"
                )
            } else if vm.calendarStatus == .notDetermined {
                Button(String(localized: "Allow Calendar Access")) { Task { await vm.requestCalendar() } }
                    .buttonStyle(.borderedProminent)
            }
        }
        .onReceive(NotificationCenter.default.publisher(for: NSApplication.didBecomeActiveNotification)) { _ in
            Task { await vm.refresh() }
        }
    }
}

