import SwiftUI

/// A translucent first-launch hint overlay that points users to the Record button.
///
/// Dismisses on tap or automatically after 10 seconds.
@MainActor
public struct TutorialOverlayView: View {
    @Binding public var isVisible: Bool

    public init(isVisible: Binding<Bool>) {
        _isVisible = isVisible
    }

    public var body: some View {
        VStack(spacing: 12) {
            Image(systemName: "arrow.up.circle.fill")
                .font(.system(size: 32))
                .foregroundStyle(.white)
            Text("Click here to start your first recording")
                .font(.headline)
                .foregroundStyle(.white)
                .multilineTextAlignment(.center)
        }
        .padding(20)
        .background(.ultraThinMaterial)
        .clipShape(RoundedRectangle(cornerRadius: 12))
        .accessibilityLabel("Tutorial: Click here to start your first recording")
        .onTapGesture {
            isVisible = false
        }
        .task {
            do {
                try await Task.sleep(nanoseconds: 10 * 1_000_000_000)
                isVisible = false
            } catch {
                // Cancelled (view disappeared) — no dismissal needed.
            }
        }
    }
}

