import Domain
import SwiftUI

/// Main window — NavigationSplitView with sidebar and detail panel.
/// TASK-022: full assembly replacing the TASK-009 skeleton.
@MainActor
public struct MainWindowView: View {
    @Environment(AppState.self) private var appState: AppState?

    @Bindable public var menuBarVM: MenuBarViewModel
    @Bindable public var libraryVM: MeetingLibraryViewModel
    @Bindable public var searchVM: SearchViewModel
    @Bindable public var detailVM: MeetingDetailViewModel
    @Bindable public var waveformVM: WaveformViewModel
    @Bindable public var commitmentsVM: CommitmentsViewModel
    public var audioPlayerVM: AudioPlayerViewModel

    public init(
        menuBarVM: MenuBarViewModel,
        libraryVM: MeetingLibraryViewModel,
        searchVM: SearchViewModel,
        detailVM: MeetingDetailViewModel,
        waveformVM: WaveformViewModel,
        commitmentsVM: CommitmentsViewModel,
        audioPlayerVM: AudioPlayerViewModel
    ) {
        self.menuBarVM = menuBarVM
        self.libraryVM = libraryVM
        self.searchVM = searchVM
        self.detailVM = detailVM
        self.waveformVM = waveformVM
        self.commitmentsVM = commitmentsVM
        self.audioPlayerVM = audioPlayerVM
    }

    public var body: some View {
        Group {
            if let appState {
                content(appState)
            } else {
                ProgressView()
            }
        }
    }

    @ViewBuilder
    private func content(_ appState: AppState) -> some View {
        NavigationSplitView(columnVisibility: .constant(.all)) {
            MeetingLibrarySidebarView(
                libraryVM: libraryVM,
                searchVM: searchVM,
                selection: Binding(
                    get: { appState.navigation.selectedMeetingID },
                    set: { appState.navigation.selectedMeetingID = $0 }
                )
            )
        } detail: {
            VStack(spacing: 0) {
                WaveformView(viewModel: waveformVM)
                ErrorBannerView(errorMessage: $libraryVM.errorMessage)
                if menuBarVM.recordingState == .recording {
                    RecordingLiveView(menuBarVM: menuBarVM)
                } else if libraryVM.meetings.isEmpty {
                    EmptyStateView {
                        Task { await menuBarVM.startRecordingTapped() }
                    }
                } else if detailVM.selectedMeeting == nil {
                    Text(String(localized: "Select a meeting"))
                        .foregroundStyle(.secondary)
                        .frame(maxWidth: .infinity, maxHeight: .infinity)
                } else {
                    CleanupProgressView(isVisible: menuBarVM.cleanupState.isRunning)
                    TabSwitcherView(selection: Binding(
                        get: { appState.navigation.selectedDetailTab },
                        set: { appState.navigation.selectedDetailTab = $0 }
                    ))
                    switch appState.navigation.selectedDetailTab {
                    case .transcript:
                        TranscriptTabView(viewModel: detailVM, audioPlayerViewModel: audioPlayerVM)
                    case .summary:
                        SummaryTabView(viewModel: detailVM)
                    case .commitments:
                        CommitmentsTabView(
                            viewModel: commitmentsVM,
                            currentMeetingId: detailVM.selectedMeeting?.id
                        )
                    case .context:
                        if let suggestionsVM = menuBarVM.contextSuggestionsVM {
                            ContextSuggestionsPanelView(viewModel: suggestionsVM)
                        } else {
                            Text(String(localized: "Context suggestions unavailable"))
                                .foregroundStyle(.secondary)
                                .accessibilityLabel(String(localized: "Context suggestions unavailable"))
                        }
                    }
                }
            }
        }
        .frame(minWidth: 800, minHeight: 600)
        .toolbar {
            ToolbarItem(placement: .primaryAction) {
                recordToolbarButton
            }
        }
        .task { await libraryVM.loadMeetingsAndCaptureError() }
    }

    private var recordToolbarButton: some View {
        Button {
            Task {
                if menuBarVM.recordingState == .recording {
                    await menuBarVM.stopRecordingTapped()
                } else {
                    await menuBarVM.startRecordingTapped()
                }
            }
        } label: {
            Label(
                menuBarVM.recordingState == .recording ? "Stop" : "Record",
                systemImage: menuBarVM.recordingState == .recording
                    ? "stop.circle.fill"
                    : "record.circle"
            )
        }
        .keyboardShortcut("r", modifiers: [.command])
        .disabled(menuBarVM.recordingState == .processing)
        .accessibilityLabel(
            menuBarVM.recordingState == .recording
                ? String(localized: "Stop recording")
                : String(localized: "Start recording")
        )
    }
}

