import AppKit
import Domain
import SwiftUI

// MARK: - Dock Bar (Phase 10)

@MainActor
public struct BroadsheetDockBar: View {
    @Environment(BroadsheetAppState.self) private var appState
    @FocusState private var askFocused: Bool

    public init() {}

    public var body: some View {
        @Bindable var appState = appState
        VStack(spacing: 0) {
            Rectangle().fill(Color.rule).frame(height: Metrics.rule)
            HStack(spacing: Metrics.unit * 2) {
                askField(appState: appState)
                Spacer()
                templateMenu
                shareMenu
            }
            .padding(.horizontal, Metrics.unit * 2)
            .frame(height: 52)
            .background(Color.bg)
        }
    }

    // MARK: - Ask Field

    private func askField(appState: BroadsheetAppState) -> some View {
        @Bindable var appState = appState
        return HStack(spacing: 6) {
            Text("✦").font(Typography.uiLabel).foregroundStyle(Color.editor)
            TextField(
                "Query the wire — ask Broadsheet about this meeting",
                text: $appState.askQuery
            )
            .font(Typography.uiLabel)
            .textFieldStyle(.plain)
            .focused($askFocused)
            .onSubmit {
                guard !appState.askQuery.isEmpty else { return }
                appState.askQuery = ""
            }
            .background(
                Button("") { askFocused = true }
                    .keyboardShortcut("l", modifiers: .command)
                    .opacity(0)
                    .accessibilityHidden(true)
            )
            if !askFocused {
                Text("⌘L").kicker().foregroundStyle(Color.ink4)
            }
        }
        .padding(.horizontal, Metrics.unit)
        .padding(.vertical, 8)
        .overlay(Rectangle().stroke(Color.midRule, lineWidth: Metrics.rule))
        .frame(maxWidth: 400)
    }

    // MARK: - Template Menu (#316)

    private var hasContent: Bool {
        appState.detailVM.transcript != nil || !appState.detailVM.segments.isEmpty
    }

    private var templateMenu: some View {
        Menu {
            ForEach(MeetingType.menuOrdered, id: \.self) { type in
                Button(type.displayName) {
                    Task { await appState.summarizeNow(meetingType: type) }
                }
            }
        } label: {
            Label("Template", systemImage: "square.grid.2x2")
                .kicker()
        }
        .buttonStyle(.plain)
        .disabled(appState.selectedMeetingID == nil || !hasContent)
        .accessibilityHint(appState.selectedMeetingID == nil ? "Select a meeting to enable templates" : "No transcript content available")
    }

    // MARK: - Share Menu (#317)

    private var shareMenu: some View {
        Menu {
            Button("Copy Summary") {
                appState.copyToClipboard(appState.detailVM.summaryMarkdownText, label: "Summary")
            }
            .disabled(appState.detailVM.summary == nil)
            .accessibilityLabel(String(localized: "Copy meeting summary to clipboard"))

            Button("Copy Transcript") {
                appState.copyToClipboard(appState.detailVM.transcript ?? "", label: "Transcript")
            }
            .disabled(appState.detailVM.transcript == nil)
            .accessibilityLabel(String(localized: "Copy meeting transcript to clipboard"))

            Divider()

            Menu("Export As...") {
                ForEach(ShareFormat.allCases, id: \.self) { format in
                    Button(format.menuLabel) {
                        Task { await appState.exportMeeting(format: format) }
                    }
                }
            }
            .disabled(appState.detailVM.transcript == nil)
        } label: {
            Label("Share", systemImage: "square.and.arrow.up")
                .kicker()
        }
        .buttonStyle(.plain)
        .disabled(appState.selectedMeetingID == nil)
    }
}

