import Charts
import Domain
import SwiftUI

@MainActor
public struct WaveformView: View {
    @Bindable public var viewModel: WaveformViewModel

    /// Static gradient constants — value types constructed once, not on every body eval.
    /// Fixes #176: LinearGradient was being re-constructed on every 30 Hz body pass.
    private static let backgroundGradient = LinearGradient(
        colors: [.cyan.opacity(0.08), .indigo.opacity(0.08), .pink.opacity(0.08)],
        startPoint: .leading,
        endPoint: .trailing
    )
    private static let foregroundGradient = LinearGradient(
        colors: [.cyan, .indigo, .pink],
        startPoint: .leading,
        endPoint: .trailing
    )

    public init(viewModel: WaveformViewModel) {
        self.viewModel = viewModel
    }

    public var body: some View {
        if viewModel.isVisible {
            chartContent
                .frame(height: 50)
                .background(Self.backgroundGradient)
                .accessibilityLabel("Audio waveform")
                .accessibilityHidden(false)
        }
    }

    private var chartContent: some View {
        // Uses magnitudes.indices + subscript access — fixes #166: avoids creating a
        // heap-allocated [(offset: Int, element: Float)] array on every 30 Hz body eval.
        Chart(viewModel.magnitudes.indices, id: \.self) { index in
            AreaMark(
                x: .value("Bin", index),
                y: .value("Magnitude", viewModel.magnitudes[index])
            )
            .interpolationMethod(.catmullRom)
            .foregroundStyle(Self.foregroundGradient)
        }
        .chartXAxis(.hidden)
        .chartYAxis(.hidden)
        .animation(.easeOut, value: viewModel.magnitudes)
    }
}

