/// Four-step first-launch onboarding: local-first explainer → mic permission → system audio → calendar.
@MainActor
public struct OnboardingView: View {
    public let onComplete: () -> Void

    @State private var step = 0
    @State var vm: OnboardingViewModel

    public init(permissionService: any PermissionService, onComplete: @escaping () -> Void) {
        self.onComplete = onComplete
        _vm = State(initialValue: OnboardingViewModel(service: permissionService))
    }

    public var body: some View {
        VStack(spacing: 32) {
            Spacer()
            stepContent
            Spacer()
            navigationButtons
        }
        .padding(40)
        .frame(width: 520, height: 420)
        .task {
            await vm.refresh()
            if vm.allPermissionsGranted {
                vm.completeOnboarding()
                onComplete()
            }
        }
        .accessibilityLabel("Onboarding")
    }

    // MARK: - Steps

    @ViewBuilder
    var stepContent: some View {
        switch step {
        case 0: welcomeStep
        case 1: micStep
        case 2: audioStep
        case 3: calendarStep
        default: calendarStep
        }
    }

    // MARK: - Navigation

    var navigationButtons: some View {
        HStack {
            if step < 3 {
                Button(String(localized: "Skip")) { onComplete() }
                    .foregroundStyle(.secondary)
            }
            Spacer()
            if step == 3 {
                Button(String(localized: "Get Started")) {
                    vm.completeOnboarding()
                    onComplete()
                }
                .buttonStyle(.borderedProminent)
                .controlSize(.large)
            } else {
                Button(String(localized: "Continue")) { step += 1 }
                    .buttonStyle(.borderedProminent)
