    public let headlines: [String]

    public init(headlines: [String]) {
        self.headlines = headlines
    }

    public var body: some View {
        if headlines.isEmpty {
            EmptyView()
        } else {
            TickerStrip(headlines: headlines)
        }
    }
}

// MARK: - TickerStrip

/// Internal implementation. Separated so the outer view can gate on `headlines.isEmpty`
/// without SwiftUI allocating the geometry/animation machinery for an empty list.
@MainActor private struct TickerStrip: View {
    let headlines: [String]

    @State private var offset: CGFloat = 0
    @State private var animationID = UUID()

    private var tickerText: String {
        headlines.joined(separator: "   ◆   ")
    }

    var body: some View {
        ZStack(alignment: .leading) {
            // Dark strip background
            Color.rule

            HStack(spacing: 0) {
                // Channel bug — pinned left, outside scroll area
                ChannelBug()

                // Scrolling content — fixed frame replacement for GeometryReader
                Text(tickerText)
                    .font(.system(size: 11, weight: .medium, design: .monospaced))
                    .foregroundStyle(Color.newsprint)
                    .fixedSize()
                    .background(
                        GeometryReader { inner in
                            Color.clear
                                .onAppear {
                                    let contentWidth = inner.size.width
                                    let viewWidth: CGFloat = 320
                                    startScrolling(contentWidth: contentWidth, viewWidth: viewWidth)
                                }
                        }
                    )
                    .offset(x: offset)
                    .frame(width: 320)
                    .clipped()
            }
        }
        .frame(height: 24)
        // .id(UUID()) intentionally tears down and recreates TickerStrip on every headline
        // change to reset the scroll position to the beginning. Acceptable at the 30s
        // refresh cadence; if cadence increases, consider resetting the offset directly.
        .onChange(of: tickerText) { _, _ in
            animationID = UUID()
        }
        .id(animationID)
        .accessibilityElement(children: .ignore)
        .accessibilityLabel("News ticker")
        .accessibilityValue(headlines.joined(separator: ", "))
    }

    // MARK: - Scroll animation

    private func startScrolling(contentWidth: CGFloat, viewWidth: CGFloat) {
        offset = viewWidth
        let duration = Double(contentWidth + viewWidth) / 60.0 // ~60 pts/sec
        withAnimation(
            .linear(duration: duration)
                .repeatForever(autoreverses: false)
        ) {
            offset = -contentWidth
        }
    }
}

