// MARK: - Notes Column

@MainActor
struct NotesColumn: View {
    @Environment(BroadsheetAppState.self) private var appState

    // swiftlint:disable no_nsformatter_instantiation
    // safe: @MainActor isolation serialises all access to this non-Sendable formatter
    @MainActor private static let timeStampFormatter: DateFormatter = {
        let f = DateFormatter()
        f.dateFormat = "HH:mm"
        return f
    }()

    // swiftlint:enable no_nsformatter_instantiation

    /// A mutation-only binding for the editor. Save is handled exclusively by
    /// `NoteEditorView.onSave` via `debouncedSaveNotes` — the setter here only
    /// updates the in-memory string so SwiftUI tracks the change.
    private var notesBinding: Binding<String> {
        Binding(
            get: { appState.detailVM.notes },
            set: { appState.detailVM.notes = $0 }
        )
    }

    private func insertTimestamp() {
        let stamp: String
        if appState.isRecording, let start = appState.recordingStartTime {
            let elapsed = Int(Date().timeIntervalSince(start))
            stamp = "[\(elapsed / 60):\(String(format: "%02d", elapsed % 60))]"
        } else {
            stamp = "[\(Self.timeStampFormatter.string(from: .now))]"
        }
        let current = appState.detailVM.notes
        let separator = current.isEmpty || current.hasSuffix("\n") ? "" : "\n"
        appState.detailVM.notes = current + separator + stamp + " "
        appState.detailVM.debouncedSaveNotes(appState.detailVM.notes)
    }

    var body: some View {
        VStack(alignment: .leading, spacing: 0) {
            // Header
            HStack {
                Text("THE NOTES").kicker()
                Spacer()
                Button {
                    insertTimestamp()
                } label: {
                    Text("⌘T STAMP").kicker()
                        .foregroundStyle(appState.isRecording ? Color.breaking : Color.ink3)
                }
                .buttonStyle(.plain)
                .keyboardShortcut("t", modifiers: .command)
                .help("Insert timestamp at cursor (⌘T)")
