import SwiftUI

// MARK: - Transcript Column

@MainActor
struct TranscriptColumn: View {
    @Environment(BroadsheetAppState.self) private var appState
    @Environment(\.textScale) private var scale
    private let bottomAnchorID = "transcript-bottom"

    var body: some View {
        VStack(spacing: 0) {
            // Fixed header — always visible, button only shows for completed meetings
            HStack {
                Text("THE DISPATCH · LIVE TRANSCRIPT").kicker()
                Spacer()
                Button {
                    // Unstructured Task is intentional: redriveTranscription is
                    // idempotent and cancels prior runs via its internal state.
                    Task { await appState.redriveTranscription() }
                } label: {
                    Text("RE-TRANSCRIBE")
                        .font(Typography.kicker)
                        .tracking(1.8)
                        .textCase(.uppercase)
                        .foregroundStyle(appState.isRecording ? Color.ink4 : Color.editor)
                }
                .buttonStyle(.plain)
                .disabled(appState.isRecording)
                .accessibilityLabel("Re-transcribe recording")
            }
            .padding(.horizontal, Metrics.unit * 3)
            .padding(.vertical, Metrics.unit)
            .overlay(Rectangle().stroke(Color.hairlineColor, lineWidth: Metrics.hairline), alignment: .bottom)

            ScrollViewReader { proxy in
                ScrollView {
                    VStack(alignment: .leading, spacing: 0) {
                        if appState.isRecording {
                            liveTranscriptView
                        } else if !appState.detailVM.segments.isEmpty {
                            diarizedTranscriptView
                        } else if let transcript = appState.detailVM.transcript {
                            Text(transcript)
                                .font(.system(size: 15 * scale, design: .serif))
                                .foregroundStyle(Color.ink)
                        } else {
                            Text("No transcript yet.")
                                .font(.system(size: 15 * scale, design: .serif))
                                .foregroundStyle(Color.ink3)
                        }
                        Color.clear.frame(height: 1).id(bottomAnchorID)
                    }
                    .padding(Metrics.unit * 3)
                }
                .background(Color.bg)
                .onChange(of: appState.liveTranscriptTurns.count) { _, _ in
                    withAnimation(.easeOut(duration: 0.15)) {
                        proxy.scrollTo(bottomAnchorID, anchor: .bottom)
                    }
                }
            } // ScrollViewReader
        } // outer VStack
    }

    @ViewBuilder
    private var diarizedTranscriptView: some View {
        let segments = appState.detailVM.segments
        let meetingId = appState.selectedMeetingID?.rawValue ?? ""
        LazyVStack(alignment: .leading, spacing: 4) {
            ForEach(segments, id: \.id) { segment in
                VStack(alignment: .leading, spacing: 2) {
                    Text(SpeakerNamer.name(speakerId: segment.speakerId.rawValue, meetingId: meetingId))
                        .font(.caption.weight(.semibold))
                        .foregroundStyle(.secondary)
                    Text(segment.text)
                        .font(.system(size: 15 * scale, design: .serif))
                        .foregroundStyle(Color.ink)
                }
                .padding(.vertical, 4)
            }
        }
    }

    @ViewBuilder
    private var liveTranscriptView: some View {
        let turns = appState.liveTranscriptTurns
        if turns.isEmpty {
            EmptyView()
        } else {
            LazyVStack(alignment: .leading, spacing: 0) {
                ForEach(turns) { turn in
                    TurnView(turn: turn)
                }
            }
        }
    }
}

// MARK: - Turn View

@MainActor
struct TurnView: View {
    let turn: TranscriptTurnDisplay
    @Environment(\.textScale) private var scale

    var body: some View {
        VStack(alignment: .leading, spacing: 2) {
            HStack(spacing: Metrics.unit) {
                Text(turn.speakerName).kicker()
                Text(turn.timestamp)
                    .font(Typography.timestamp)
                    .foregroundStyle(Color.ink3)
                Text(turn.channelLabel)
                    .font(Typography.timestamp)
                    .foregroundStyle(Color.ink4)
            }
            Text(turn.text)
                .font(.system(size: 15 * scale, weight: turn.isCurrent ? .semibold : .regular, design: .serif))
                .foregroundStyle(Color.ink)
        }
        .padding(.vertical, Metrics.unit * 0.75)
    }
}
